PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS persons (id TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('ACTIVE','SUSPENDED','CLOSED')), created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, person_id TEXT NOT NULL UNIQUE REFERENCES persons(id), email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), csrf_hash TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claims (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), attribute TEXT NOT NULL, value_json TEXT NOT NULL, source_type TEXT NOT NULL, source_reference TEXT, assurance TEXT NOT NULL, verification_status TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES accounts(id));
CREATE INDEX IF NOT EXISTS ix_claims_person_attribute ON claims(person_id,attribute,status);
CREATE TABLE IF NOT EXISTS credentials (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), type TEXT NOT NULL, issuer TEXT NOT NULL, external_identifier TEXT, issued_at TEXT, expires_at TEXT, verification_status TEXT NOT NULL CHECK(verification_status IN ('UNVERIFIED','PENDING','VERIFIED','REJECTED','EXPIRED')), source_reference TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), claim_id TEXT REFERENCES claims(id), credential_id TEXT REFERENCES credentials(id), source_type TEXT NOT NULL, source_reference TEXT, captured_at TEXT NOT NULL, verification_method TEXT NOT NULL, assurance_level TEXT NOT NULL, evidence_status TEXT NOT NULL, artifact_hash TEXT, created_by TEXT NOT NULL REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS conflicts (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), attribute TEXT NOT NULL, claim_ids_json TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('OPEN','UNDER_REVIEW','RESOLVED','DISPUTED')), resolution_reference TEXT, opened_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, required_fields_json TEXT NOT NULL, organization TEXT NOT NULL, adapter_mode TEXT NOT NULL CHECK(adapter_mode IN ('MOCK','SANDBOX','PRODUCTION')), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS applications (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), service_id TEXT NOT NULL REFERENCES services(id), status TEXT NOT NULL, readiness_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS data_requests (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), requester TEXT NOT NULL, purpose TEXT NOT NULL, legal_basis TEXT NOT NULL, requested_fields_json TEXT NOT NULL, service_id TEXT REFERENCES services(id), expires_at TEXT NOT NULL, policy_outcome TEXT NOT NULL, policy_reason TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consents (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES data_requests(id), person_id TEXT NOT NULL REFERENCES persons(id), requester TEXT NOT NULL, purpose TEXT NOT NULL, legal_basis TEXT NOT NULL, scope_json TEXT NOT NULL, presented_version TEXT NOT NULL, granted_at TEXT NOT NULL, expires_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('ACTIVE','REVOKED','EXPIRED','SUPERSEDED')), auth_account_id TEXT NOT NULL REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS policy_decisions (id TEXT PRIMARY KEY, subject_person_id TEXT NOT NULL REFERENCES persons(id), action TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('ALLOW','REVIEW','DENY')), reason TEXT NOT NULL, policy_version TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES data_requests(id), consent_id TEXT NOT NULL REFERENCES consents(id), person_id TEXT NOT NULL REFERENCES persons(id), adapter_id TEXT NOT NULL, adapter_mode TEXT NOT NULL, fields_json TEXT NOT NULL, package_json TEXT NOT NULL, receipt_json TEXT NOT NULL, idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(person_id,idempotency_key));
CREATE TABLE IF NOT EXISTS platform_controls (name TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT, purpose TEXT, policy_decision_id TEXT, result TEXT NOT NULL, correlation_id TEXT NOT NULL, before_hash TEXT, after_hash TEXT, previous_hash TEXT, event_hash TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'audit events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'audit events are append-only'); END;
CREATE TABLE IF NOT EXISTS family_networks (id TEXT PRIMARY KEY, owner_person_id TEXT NOT NULL REFERENCES persons(id), name TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'PRIVATE', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS family_members (network_id TEXT NOT NULL REFERENCES family_networks(id), person_id TEXT NOT NULL REFERENCES persons(id), role TEXT NOT NULL, joined_at TEXT NOT NULL, PRIMARY KEY(network_id,person_id));
CREATE TABLE IF NOT EXISTS relationships (id TEXT PRIMARY KEY, network_id TEXT NOT NULL REFERENCES family_networks(id), subject_person_id TEXT NOT NULL REFERENCES persons(id), related_label TEXT NOT NULL, relationship_type TEXT NOT NULL, evidence_level TEXT NOT NULL, state TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'FAMILY', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS family_items (id TEXT PRIMARY KEY, network_id TEXT NOT NULL REFERENCES family_networks(id), owner_person_id TEXT NOT NULL REFERENCES persons(id), item_type TEXT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, evidence_level TEXT NOT NULL, certainty TEXT NOT NULL, visibility TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS life_events (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), event_type TEXT NOT NULL, occurred_range TEXT, evidence_json TEXT NOT NULL, risk TEXT NOT NULL, state TEXT NOT NULL, impact_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS legacy_vaults (id TEXT PRIMARY KEY, owner_person_id TEXT NOT NULL UNIQUE REFERENCES persons(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS legacy_items (id TEXT PRIMARY KEY, vault_id TEXT NOT NULL REFERENCES legacy_vaults(id), owner_person_id TEXT NOT NULL REFERENCES persons(id), title TEXT NOT NULL, content TEXT NOT NULL, classification TEXT NOT NULL, release_mode TEXT NOT NULL, trigger_type TEXT NOT NULL, custodians_json TEXT NOT NULL, released_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES persons(id), category TEXT NOT NULL, message TEXT NOT NULL, sensitive INTEGER NOT NULL DEFAULT 0, acknowledged_at TEXT, created_at TEXT NOT NULL);
